export const GENERAL_ECOLOGICAL_SWMS_CONTROLLED_HTML = "<article class=\"gswms__paper\">\n<div class=\"gswms__document-header\" style=\"display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #2f7d3f;padding:4px 0 6px;margin-bottom:2px\">\n<img alt=\"Ecology Consulting\" src=\"__GENERAL_SWMS_LOGO__\" style=\"height:26px\"/>\n<div style=\"text-align:right;font-size:8.5px;color:#5b6b76;line-height:1.3\">\n<div style=\"font-weight:700;color:#2f7d3f\">SAFE WORK METHOD STATEMENT · SWMS00</div>\n<div>General ecological survey work</div>\n</div>\n</div>\n<div class=\"gswms__document-footer\" style=\"display:flex;justify-content:space-between;border-top:1px solid #cdd5db;padding-top:5px;font-size:8px;color:#82909b\">\n<span>Ecology Consulting Pty Ltd · ABN 68 647 633 163 · ecologyconsulting.au</span>\n<span>Doc: EC-SWMS00 · Rev 1.0 · Uncontrolled when printed</span>\n</div>\n<div style=\"text-align:center;padding:52px 0 6px\">\n<img alt=\"Ecology Consulting\" src=\"__GENERAL_SWMS_LOGO__\" style=\"height:64px;display:block;margin:0 auto 10px\"/>\n<div style=\"display:inline-block;background:#2f7d3f;color:#fff;font-size:11px;font-weight:700;letter-spacing:2px;padding:4px 16px;border-radius:2px;margin-bottom:10px\">SWMS00</div>\n<h1 style=\"font-size:24px;color:#2f7d3f;letter-spacing:0.3px\">Safe Work Method Statement</h1>\n<h2 style=\"font-size:15px;color:#3f93cf;font-weight:600;margin:5px auto 0;max-width:800px\">General ecological survey work</h2>\n</div>\n<table data-source-table=\"0\" style=\"width:100%;border-collapse:collapse;font-size:10.5px;margin:6px 0 14px\"><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:18%\">Document number</td><td style=\"border:1px solid #cdd5db;padding:6px 9px;width:32%\">EC-SWMS00</td><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:18%\">Revision</td><td style=\"border:1px solid #cdd5db;padding:6px 9px;width:32%\">1.0</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Prepared by</td><td style=\"border:1px solid #cdd5db;padding:6px 9px\">Ecology Consulting — WHS / Field team</td><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Document release date</td><td data-blank-field=\"documentReleaseDate\" style=\"border:1px solid #cdd5db;padding:6px 9px\"><span data-field=\"documentReleaseDate\"></span></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Approved by</td><td style=\"border:1px solid #cdd5db;padding:6px 9px\">Tony Webster — Managing Director / WHS Officer</td><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Next review</td><td data-blank-field=\"nextReview\" style=\"border:1px solid #cdd5db;padding:6px 9px\"><span data-field=\"nextReview\"></span></td></tr>\n</tbody></table>\n<div style=\"border:1px solid #d8c39e;background:#faf6ef;border-left:4px solid #b5854f;padding:8px 12px;font-size:9.5px;color:#5b4a2e;margin-bottom:14px\">\n<strong>Note:</strong> Work must be performed in accordance with this Safe Work Method Statement (SWMS). This SWMS must be kept and available for inspection until the work is completed. If revised, every version must be kept. If a notifiable incident occurs in relation to the work in this SWMS, the SWMS must be kept for at least two years from the date of the notifiable incident. This SWMS is accessed and acknowledged through the Ecology Consulting digital WHS platform; field forms are submitted from site and reviewed centrally by the administration team.\n  </div>\n<div style=\"border:1px solid #9cc3e0;background:#eaf1f6;border-left:4px solid #3f93cf;padding:8px 12px;font-size:9.8px;margin-bottom:14px\">\n<strong>Scope &amp; limitations:</strong> Applies to all routine field-based ecological survey work, including flora and fauna surveys, habitat and vegetation condition assessments, threatened species surveys, camera trap and acoustic device deployment and retrieval, and general site inspections. <strong>This SWMS sets the baseline controls for all fieldwork.</strong> Where a survey involves high risk construction work — falls over two metres, confined spaces, tunnels, energised electrical services, traffic corridors, mobile plant, water with a drowning risk, or asbestos — the relevant task-specific SWMS must also be applied — all 19 high risk construction work categories, and the SWMS that covers each, are set out in the high risk construction work section of this document. Ecology Consulting personnel do not operate plant, undertake excavation, climb trees, or enter confined spaces or water unless the relevant SWMS, training and authorisation are in place.\n  </div>\n<h3 style=\"font-size:14px;color:#fff;background:#2f7d3f;padding:8px 12px;margin:0\">Project &amp; PCBU details</h3>\n<table data-source-table=\"1\" style=\"width:100%;border-collapse:collapse;font-size:10.5px;margin:0 0 14px\"><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:24%\">Person conducting a business or undertaking (PCBU)</td><td style=\"border:1px solid #cdd5db;padding:6px 9px;width:38%\">Ecology Consulting Pty Ltd · ABN 68 647 633 163</td><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:14%\">Contact number</td><td style=\"border:1px solid #cdd5db;padding:6px 9px;width:24%\">0472 569 988 (office / Check-in)</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">EC offices</td><td colspan=\"3\" style=\"border:1px solid #cdd5db;padding:6px 9px\">34 Atchison St, Wollongong NSW 2500 · 42 Goulburn St, Crookwell NSW 2583 · 473 Townsend St, Albury NSW 2640</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Client / Principal Contractor</td><td colspan=\"3\" data-blank-field=\"client\" style=\"border:1px solid #cdd5db;padding:6px 9px\"><span data-field=\"client\"></span></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Work activity</td><td colspan=\"3\" style=\"border:1px solid #cdd5db;padding:6px 9px\">General ecological survey work — flora and fauna surveys, habitat assessment, vegetation mapping, targeted threatened species surveys, fauna trapping and handling, spotlighting, camera and acoustic device deployment, and site inspection, in accordance with Ecology Consulting SOPs and JSAs.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Workplace location</td><td colspan=\"3\" data-blank-field=\"workplace\" style=\"border:1px solid #cdd5db;padding:6px 9px\"><span data-field=\"workplace\"></span></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Field work duration</td><td colspan=\"3\" data-blank-field=\"fieldDuration\" style=\"border:1px solid #cdd5db;padding:6px 9px\"><span data-field=\"fieldDuration\"></span></td></tr>\n</tbody></table>\n<h3 style=\"font-size:14px;color:#fff;background:#2f7d3f;padding:8px 12px;margin:0\">Legislation, codes of practice &amp; standards</h3>\n<table data-source-table=\"2\" style=\"width:100%;border-collapse:collapse;font-size:10px;margin:0 0 14px\"><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:24%\">Acts &amp; Regulations</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Work Health and Safety Act 2011 (NSW) and the Work Health and Safety Regulation (NSW); Work Health and Safety Act 2011 (Cth) and WHS Regulations 2011 (Cth) where work is on Commonwealth land or for a Commonwealth entity (Comcare jurisdiction); Work Health and Safety Act 2011 (ACT) and WHS Regulation 2011 (ACT) for works in the ACT.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Codes of Practice</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Safe Work Australia model Codes as adopted in NSW and the ACT: <em>How to manage work health and safety risks</em>; <em>Work health and safety consultation, cooperation and coordination</em>; <em>Construction work</em>; <em>First aid in the workplace</em>; <em>Managing the work environment and facilities</em>; <em>Preparation of safe work method statements for construction work</em>. <em>Hazardous manual tasks</em>; <em>Managing risks of hazardous chemicals in the workplace</em>. SafeWork NSW guidance on remote and isolated work, working in heat and UV exposure.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Standards &amp; guidance</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">AS/NZS 1801 and AS/NZS 1800 Occupational protective helmets; AS/NZS 4602 High visibility safety garments; AS/NZS 2210 Occupational protective footwear; AS/NZS 1067 Sunglasses; AS 4758 Personal flotation devices. NPWS PPE requirements on NPWS managed lands, including approved helmets in uncontrolled forested environments containing trees greater than four metres in height.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">EC WHS documentation</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">EC Work Health and Safety Management System and WHS Handbook; EC Risk Management Processes (EC-RMP-FRM-001); EC Hazard Register and Trigger Action Response List (TARL); Pre-Mobilisation Checklist; Pre-Travel Vehicle Safety Checklist; Journey Management Plan; Daily Toolbox Talk; site-specific Emergency Response Plan (ERP); JSA — General Field Surveys; JSA — Remote and Isolated Work; SOP — Journey Management; SOP — Terrestrial Fauna; SOP — Fieldwork Biosecurity. Biodiversity Conservation Act 2016 (NSW); National Parks and Wildlife Act 1974 (NSW); Environment Protection and Biodiversity Conservation Act 1999 (Cth); Animal Research Act 1985 (NSW), Scientific Licence and Animal Research Authority as applicable.</td></tr>\n</tbody></table>\n<h3 style=\"font-size:14px;color:#fff;background:#2f7d3f;padding:8px 12px;margin:0\">Mandatory personal protective equipment &amp; field equipment</h3>\n<p style=\"font-size:9.5px;color:#5b6b76;margin:6px 0 6px\">Confirmed present and serviceable on the Pre-Mobilisation Checklist and verified by the Field Lead at the Daily Toolbox Talk. Faulty items are tagged out and removed from service.</p>\n<table data-source-table=\"3\" style=\"width:100%;border-collapse:collapse;font-size:9.5px;margin:0 0 8px;text-align:center\"><tbody><tr><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Hard Hat / Approved Helmet</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Safety Glasses</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Gloves</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Hearing Protection</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Hi-Vis Clothing</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Long Sleeves &amp; Trousers</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Sun Safe PPE</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Gaiters</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Lace-up / Capped Boots</td></tr><tr><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe01\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe02\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe03\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe04\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe05\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe06\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe07\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe08\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"ppe.ppe09\"></span></td></tr></tbody></table>\n<table data-source-table=\"4\" style=\"width:100%;border-collapse:collapse;font-size:9.5px;margin:0 0 8px;text-align:center\"><tbody><tr><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">Mobile Phone</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">UHF Radio</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">In Reach / Satellite</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">PLB (if required)</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">GPS + Spare Battery</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">Headlamp + Spares</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">Remote First Aid Kit</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">Snake Bite Kit</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#eaf1f6;font-weight:700\">Fire Extinguisher</td></tr><tr><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment01\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment02\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment03\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment04\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment05\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment06\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment07\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment08\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment09\"></span></td></tr></tbody></table>\n<table data-source-table=\"5\" style=\"width:100%;border-collapse:collapse;font-size:9.5px;margin:0 0 14px;text-align:center\"><tbody><tr><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Water + Reserve</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Electrolytes</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Additional Food</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Insect Repellent</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Sunscreen</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Hygiene / Biosecurity Kit</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Thermal Blanket</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Whistle &amp; Mirror</td><td style=\"border:1px solid #cdd5db;padding:8px 6px;background:#f4f7f2;font-weight:700\">Maps / Route Plan</td></tr><tr><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment10\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment11\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment12\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment13\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment14\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment15\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment16\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment17\"></span></td><td style=\"border:1px solid #cdd5db;padding:6px\"><span data-check=\"equipment.equipment18\"></span></td></tr></tbody></table>\n<h3 style=\"font-size:14px;color:#fff;background:#2f7d3f;padding:8px 12px;margin:0\">Hierarchy of controls</h3>\n<table data-source-table=\"6\" style=\"width:100%;border-collapse:collapse;font-size:10px;margin:0 0 14px\"><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:16%\">Eliminate</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Avoid the hazard — postpone surveys in extreme heat, high fire danger, storms or flood; avoid hazardous trees, unstable ground and water edges; use camera traps, acoustic recorders, remote sensing or existing data where they meet the survey objective.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:16%\">Substitute</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Use lower-risk methods, routes and timing — survey from formed tracks and safe ground, use extendable tools and binoculars instead of approaching hazards, and schedule effort into cooler parts of the day.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:16%\">Isolate</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Separate people from hazards — exclusion zones around hazardous trees, plant, water edges, drop-offs and other site activities; shelter in vehicles during lightning or threatening behaviour.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:16%\">Engineer</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Four-wheel-drive vehicles with recovery equipment, redundant communications, shade shelters and vehicle air conditioning, appropriate fauna handling and trapping equipment, and vehicle-mounted fire extinguishers.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:16%\">Administrative</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">This SWMS and task-specific SWMS, JSAs and SOPs; Pre-Mobilisation Checklist; Journey Management Plan; Daily Toolbox Talk; mandatory check-ins; minimum two-person teams for remote work; weather, fire and flood monitoring; fatigue and hydration protocols; verified training; stop-work triggers.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:16%\">PPE</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Last line of defence — helmet, sun-safe PPE, long sleeves and trousers, gaiters, boots, gloves, eye and hearing protection, hi-vis and task-specific PPE.</td></tr>\n</tbody></table>\n<h2 style=\"break-before:page;font-size:16px;color:#fff;background:#2f7d3f;padding:9px 13px;margin:0\">Hazards &amp; controls — planning, travel and site set-up</h2>\n<p style=\"font-size:10px;color:#5b6b76;margin:5px 0 8px\">Applies to every field deployment.</p>\n<table data-source-table=\"7\" style=\"width:100%;border-collapse:collapse;font-size:9.8px;margin:0 0 14px\">\n<thead><tr>\n<th style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 9px;text-align:left;width:24%\">What are the hazards &amp; risks</th>\n<th style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 9px;text-align:left;width:54%\">What are the control measures</th>\n<th style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 9px;text-align:left;width:22%\">Select relevant controls<br/><span style=\"font-weight:400;font-size:8px\">(completed onsite by Field Lead)</span></th>\n</tr></thead><tbody>\n<tr><td colspan=\"3\" style=\"border:1px solid #cdd5db;background:#eef4ea;color:#2f7d3f;font-weight:700;padding:6px 10px\">Planning, preparation and travelling to site</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Inadequate planning leading to uncontrolled risk; unfit or untrained personnel</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Attend the pre-field meeting with the Project Lead and Project Manager to review scope, methodology and expected hazards; confirm site access, keys, codes, inductions and property constraints; and confirm all staff are trained, competent and fit for work. Medical concerns are disclosed privately to the Field Lead. Review this SWMS, the relevant JSA and SOP, the Field Plan and the site-specific ERP. Verify training currency — workers are not mobilised with expired mandatory training.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control001\"></span> Pre-field meeting</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control002\"></span> SWMS / JSA / SOP reviewed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control003\"></span> ERP reviewed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control004\"></span> Training verified</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control005\"></span> Medical disclosures</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Vehicle failure, missing safety equipment or fatigue during travel</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Complete the Pre-Travel Vehicle Safety Checklist — first aid kit, extinguisher, spare tyre, torch, water and PPE present; vehicle free from leaks, faults or damage; electrical issues visually inspected only and tagged out if unsafe. Complete the Journey Management Plan. Minimum 10-hour rest between shifts before driving; personal fatigue self-assessment before departure; rest breaks every two hours; carry water, snacks and electrolytes; second driver for long or remote trips where practicable. Zero blood alcohol concentration applies to all work driving.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control006\"></span> Vehicle checklist done</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control007\"></span> JMP completed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control008\"></span> 10-hr rest confirmed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control009\"></span> Fatigue self-assessment</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Travelling into fire, flood, storm, smoke or hazardous road conditions</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Complete the Pre-Travel Environmental and Hazard Check using BOM weather warnings, Hazards Near Me, RFS fire danger ratings, Air Quality Index, lightning trackers, Live Traffic NSW and telecommunications coverage maps. <strong>Do not travel</strong> where there are emergency warning fire events, hazardous air quality, active storm warnings or flooded roads. Never drive through floodwater under any circumstance. If conditions change, stop, reassess and notify the Communication Officer.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control010\"></span> BOM / Hazards Near Me</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control011\"></span> RFS rating checked</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control012\"></span> AQI checked</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control013\"></span> Live Traffic NSW</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control014\"></span> Coverage checked</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Hazards not identified, assessed or communicated before work commences</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">All team members participate in a pre-commencement Daily Toolbox Talk led on site by the Field Lead and documented on the EC WHS form — site-specific hazards identified; collaborative risk assessment using the EC risk matrix (rating one to six) with agreed controls and a revised residual rating; PPE and equipment readiness confirmed; ERP reviewed and Emergency Meeting Point identified; communication and check-in requirements confirmed; health or access needs disclosed privately; and worker sign-on confirming understanding and fitness for work. Hazards already in the EC Hazard Register are managed under the TARL. <strong>No worker commences without sign-on.</strong></td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control015\"></span> Toolbox talk held</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control016\"></span> Risk assessment rated</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control017\"></span> Emergency Meeting Point</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control018\"></span> All workers signed on</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Loss of contact with the field team; delayed emergency response</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Mandatory check-ins with the Communication Officer (0472 569 988) before departing base, on arrival at site or accommodation, before leaving site, and on return to base. Every check-in must be acknowledged. A missed or unacknowledged check-in triggers escalation through the Communication Officer, Project Lead or Project Manager, and the WHS Officer, and is grounds for activating the ERP. Carry redundant communications — mobile phone, UHF radio and In Reach or satellite communicator, with a PLB where remoteness warrants. Roles are assigned at the toolbox talk: Field Lead, Communication Officer and workers.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control019\"></span> Check-in schedule agreed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control020\"></span> Comms tested</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control021\"></span> Roles assigned</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control022\"></span> Escalation briefed</label></td></tr>\n<tr><td colspan=\"3\" style=\"border:1px solid #cdd5db;background:#eef4ea;color:#2f7d3f;font-weight:700;padding:6px 10px\">Arrival and site set-up</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Unauthorised or unsafe site access; unknown site hazards; conflict with landholders or other site users</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Confirm access permission, keys, gate codes and landholder contact before arrival. Complete any client or Principal Contractor induction and sign-in. Identify other activities on site — plant, livestock, shooting, spraying, forestry or construction — and agree separation with the site contact. Leave gates as found. Comply with all property, client and NPWS instructions.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control023\"></span> Access confirmed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control024\"></span> Induction / sign-in</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control025\"></span> Site activities identified</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control026\"></span> Gates left as found</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Vehicle rollover, bogging or roll-away when parking; blocked egress in an emergency</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Park on firm, level ground clear of soft verges, embankments, dry grass and hazardous trees. Park nose-out for rapid evacuation and do not block access tracks. Apply the handbrake and confirm the vehicle is stable before leaving it. Record vehicle GPS coordinates.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control027\"></span> Firm level parking</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control028\"></span> Clear of trees &amp; dry grass</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control029\"></span> Nose-out</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control030\"></span> GPS recorded</label></td></tr>\n</tbody></table>\n<h2 style=\"break-before:page;font-size:16px;color:#fff;background:#3f93cf;padding:9px 13px;margin:0\">Hazards &amp; controls — field survey activities</h2>\n<p style=\"font-size:10px;color:#5b6b76;margin:5px 0 8px\">Assess at the toolbox talk and reassess as conditions or tasks change.</p>\n<table data-source-table=\"8\" style=\"width:100%;border-collapse:collapse;font-size:9.8px;margin:0 0 14px\">\n<thead><tr>\n<th style=\"border:1px solid #2f7fb5;background:#3f93cf;color:#fff;padding:7px 9px;text-align:left;width:24%\">What are the hazards &amp; risks</th>\n<th style=\"border:1px solid #2f7fb5;background:#3f93cf;color:#fff;padding:7px 9px;text-align:left;width:54%\">What are the control measures</th>\n<th style=\"border:1px solid #2f7fb5;background:#3f93cf;color:#fff;padding:7px 9px;text-align:left;width:22%\">Select relevant controls<br/><span style=\"font-weight:400;font-size:8px\">(completed onsite by Field Lead)</span></th>\n</tr></thead><tbody>\n<tr><td colspan=\"3\" style=\"border:1px solid #cdd5db;background:#eef4ea;color:#2f7d3f;font-weight:700;padding:6px 10px\">Moving through the survey area</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Slips, trips and falls on uneven, steep, wet, vegetated or fire-affected ground</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Plan and brief traverse routes; avoid steep slopes, loose rock, log piles, soft sediment and dense regrowth where a safer route exists. Move deliberately and test footing. Wear lace-up boots with good tread and gaiters. Carry equipment in a backpack to keep hands free. <strong>Stop moving when recording data</strong> — do not walk while using phones, GPS or data sheets. Reassess ground after rain and in burnt areas where stumps and root plates may be hollow.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control031\"></span> Route planned</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control032\"></span> Footwear + gaiters</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control033\"></span> Stop to record</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control034\"></span> Ground reassessed</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Struck by falling limbs, hanging branches or trees</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Visually assess trees on arrival and throughout the day for dead or hanging limbs, dead standing trees, splits, lean, fire or flood damage and decayed butts. Keep at least one tree length from hazardous trees; do not work, rest, eat or park beneath them. Relocate plots, transects and device locations away from hazardous trees. <strong>Cease work beneath trees in high wind and during or after storms.</strong> Wear an approved helmet in uncontrolled forest with trees greater than four metres in height (NPWS requirement).</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control035\"></span> Trees assessed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control036\"></span> Exclusion kept</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control037\"></span> Plots relocated</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control038\"></span> Helmet worn (&gt;4 m trees)</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Becoming lost or separated; navigation failure</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Carry a charged GPS with spare batteries and paper maps. Agree transect start and end points, a rendezvous point and a return time before separating, and maintain visual or radio contact. If lost: stop, stay put, signal and contact the Communication Officer.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control039\"></span> GPS + maps</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control040\"></span> Rendezvous &amp; return time</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control041\"></span> Contact maintained</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Eye and skin injury from vegetation, thorns and sharp objects</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Wear safety glasses when pushing through vegetation, long sleeves, trousers and gloves. Do not handle sharps, glass or rubbish by hand. Cover cuts and abrasions.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control042\"></span> Eye protection</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control043\"></span> Skin covered</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control044\"></span> No sharps handling</label></td></tr>\n<tr><td colspan=\"3\" style=\"border:1px solid #cdd5db;background:#eef4ea;color:#2f7d3f;font-weight:700;padding:6px 10px\">Survey methods and equipment</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Musculoskeletal injury from manual handling — traps, batteries, water, star pickets and survey gear</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Assess the load before lifting. Use team lifts, split loads and make multiple trips rather than overloading. Use correct lifting technique and avoid twisting. Stage equipment to minimise carry distances over rough ground. Use a post driver with gloves, eye and hearing protection when installing star pickets, and confirm no underground services before driving any picket.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control045\"></span> Load assessed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control046\"></span> Team lift / split loads</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control047\"></span> Post driver PPE</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control048\"></span> Services checked</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Hazards during camera and acoustic device deployment — working at height, overreaching, hazardous trees</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Mount devices from ground level only, at a height reachable without ladders or climbing. Do not climb trees. Select mounting trees that are sound and free of overhead hazards. Use the correct straps and tools; carry long items horizontally.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control049\"></span> Ground-level mounting</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control050\"></span> No climbing</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control051\"></span> Sound tree selected</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Night work and spotlighting — reduced visibility, disorientation, vehicle hazards</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Plan night work in the JMP with shortened check-in intervals and In Reach carried. Walk routes and identify hazards in daylight beforehand where practicable. Carry a charged headlamp and torch with spares. Minimum two-person teams. When spotlighting from a vehicle, the driver does not operate the spotlight; drive at walking pace on known tracks only, and no-one rides outside the cabin.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control052\"></span> Daylight recce</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control053\"></span> Lighting + spares</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control054\"></span> Two-person team</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control055\"></span> Driver does not spotlight</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Chemical exposure — preservatives, fuel, disinfectants, landholder agricultural chemicals</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Use only chemicals listed in the SOP with Safety Data Sheets available. Wear gloves and eye protection when handling. Store and transport chemicals in labelled, sealed containers, separate from food and water. Do not handle unfamiliar chemicals; keep clear of spraying areas. Poisons Information Hotline 13 11 26.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control056\"></span> SDS available</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control057\"></span> Gloves + eye protection</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control058\"></span> Labelled storage</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control059\"></span> Clear of spraying</label></td></tr>\n<tr><td colspan=\"3\" style=\"border:1px solid #cdd5db;background:#eef4ea;color:#2f7d3f;font-weight:700;padding:6px 10px\">Fauna, biological and biosecurity hazards</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Snake bite</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Treat all snakes as venomous. Do not approach or handle snakes unless trained and it is necessary for safety. Wear gaiters, boots and long trousers. Watch foot placement and never place hands or feet where they cannot be seen; lift cover objects with a tool, towards you. Every team carries a snake bite kit. First aid: pressure immobilisation, keep the casualty still, call 000, evacuate to the hospital identified in the ERP.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control060\"></span> Gaiters + boots</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control061\"></span> Snake bite kit</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control062\"></span> Tool to lift cover</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control063\"></span> Hospital identified</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Bites, scratches and zoonotic disease from fauna handling; harm or distress to animals</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Only trained personnel handle fauna, under the applicable Scientific Licence and Animal Research Authority and in accordance with SOP — Terrestrial Fauna. Minimise handling time; wear appropriate gloves. <strong>Do not handle bats or flying-foxes unless vaccinated and authorised</strong> — any bat bite or scratch requires immediate washing for 15 minutes and urgent medical attention. Check traps at the required intervals and in extreme weather. Injured wildlife: 1300 094 737.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control064\"></span> Handling training</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control065\"></span> Licence / ARA current</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control066\"></span> No unvaccinated bat contact</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control067\"></span> Trap check schedule</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Ticks, leeches, spiders, ants, bees and wasps; anaphylaxis</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Wear long sleeves, trousers and gaiters; apply repellent. Check for ticks at the end of each day. Workers with severe allergies disclose this privately to the Field Lead, carry their adrenaline auto-injector, and the team is briefed on its location and use. Avoid nests and hives; withdraw and relocate.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control068\"></span> Repellent</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control069\"></span> Tick checks</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control070\"></span> Allergy disclosures</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control071\"></span> Auto-injector located</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Contact with scats, carcasses, contaminated water and soil; Q fever, leptospirosis, psittacosis</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Avoid direct contact with scats, carcasses and urine-soaked material; use gloves and tools. Do not disturb dry guano or dusty scats — use a P2 respirator where disturbance is unavoidable. Do not drink or wash in surface water. Wash or sanitise hands before eating and after handling animals or samples. Workers who develop flu-like symptoms after fieldwork seek medical advice and disclose the exposure.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control072\"></span> Gloves / tools used</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control073\"></span> P2 where required</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control074\"></span> Hand hygiene</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control075\"></span> Symptom advice briefed</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Spread of pathogens, weeds and disease between sites</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Follow SOP — Fieldwork Biosecurity and any NPWS or client hygiene protocol. Clean and disinfect boots, gaiters, equipment and vehicles between sites and catchments. Carry a hygiene kit. Avoid moving soil, mud, water and plant material between sites.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control076\"></span> Hygiene kit</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control077\"></span> Boots / gear cleaned</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control078\"></span> Vehicle cleaned</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control079\"></span> Protocol followed</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Aggressive livestock, dogs or large native fauna</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Keep clear of livestock, particularly bulls and animals with young. Close gates behind you. Do not approach unknown dogs. Give kangaroos, emus and cassowary-type fauna a wide berth; withdraw slowly and keep a barrier or vehicle between you and the animal.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control080\"></span> Livestock avoided</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control081\"></span> Withdrawal briefed</label></td></tr>\n</tbody></table>\n<h2 style=\"break-before:page;font-size:16px;color:#fff;background:#b5854f;padding:9px 13px;margin:0\">Hazards &amp; controls — environment, people and wellbeing</h2>\n<p style=\"font-size:10px;color:#5b6b76;margin:5px 0 8px\">Managed against the EC Hazard Register and Trigger Action Response List.</p>\n<table data-source-table=\"9\" style=\"width:100%;border-collapse:collapse;font-size:9.8px;margin:0 0 14px\">\n<thead><tr>\n<th style=\"border:1px solid #96692f;background:#b5854f;color:#fff;padding:7px 9px;text-align:left;width:24%\">What are the hazards &amp; risks</th>\n<th style=\"border:1px solid #96692f;background:#b5854f;color:#fff;padding:7px 9px;text-align:left;width:54%\">What are the control measures</th>\n<th style=\"border:1px solid #96692f;background:#b5854f;color:#fff;padding:7px 9px;text-align:left;width:22%\">Select relevant controls<br/><span style=\"font-weight:400;font-size:8px\">(completed onsite by Field Lead)</span></th>\n</tr></thead><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Heat stress, dehydration and sunburn; UV exposure</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Schedule survey effort into cooler parts of the day. Increase rest breaks in shade or air conditioning. Carry ample water plus a reserve and electrolytes. Wear sun-safe PPE — long sleeves, wide-brim hat, sunglasses and SPF 50+ sunscreen, reapplied regularly. Buddy-monitor for heat illness. <strong>Cease work immediately</strong> on dizziness, nausea, headache or confusion; cool, rehydrate and notify the Communication Officer.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control082\"></span> Cooler scheduling</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control083\"></span> Water + electrolytes</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control084\"></span> Sun-safe PPE</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control085\"></span> Buddy monitoring</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Cold exposure and hypothermia; wet conditions</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Carry wet and cold weather clothing, a thermal blanket and spare dry clothing. Monitor for shivering, fatigue and confusion. Shorten exposure in cold, wet or windy conditions.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control086\"></span> Cold weather gear</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control087\"></span> Dry clothing</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control088\"></span> Exposure limited</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Bushfire and smoke</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Check RFS fire danger ratings, Hazards Near Me and the Air Quality Index daily and monitor during the day. <strong>Do not travel or work where there is an emergency warning fire event or hazardous air quality.</strong> Brief two egress routes and the Emergency Meeting Point. Park nose-out on cleared ground. No naked flames; follow total fire ban requirements. Keep vehicles off dry grass — exhausts can ignite it.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control089\"></span> RFS / AQI checked</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control090\"></span> Two egress routes</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control091\"></span> Total fire ban observed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control092\"></span> Off dry grass</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Storms, lightning, high wind and flash flooding</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Monitor BOM warnings and a lightning tracker. Suspend work during storms or lightning and shelter in a hard-topped vehicle, not under trees. Never drive through floodwater. Avoid creek crossings and low-lying areas during or after heavy rain. Reassess trees and ground before resuming. Where work is near water, apply SWMS18.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control093\"></span> Lightning tracker</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control094\"></span> Shelter identified</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control095\"></span> No floodwater crossing</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control096\"></span> SWMS18 (water)</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Fatigue causing poor decisions or injury</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Plan realistic daily workloads and finish times. Minimum 10-hour rest between shifts. Regular breaks; rotate tasks. Stop work if fatigue affects safety and notify the Communication Officer. Night work is factored into rest requirements for the following day.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control097\"></span> Realistic workload</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control098\"></span> 10-hr rest</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control099\"></span> Breaks scheduled</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Remote or isolated work; loss of contact</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Minimum two-person teams for remote or isolated work. Carry redundant communications. Complete all four mandatory check-ins and any interim check-ins set in the JMP. A missed or unacknowledged check-in triggers escalation and ERP activation. See JSA — Remote and Isolated Work.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control100\"></span> Two-person team</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control101\"></span> Redundant comms</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control102\"></span> Check-ins completed</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Aggressive or threatening behaviour from members of the public or landholders</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Stay calm and do not escalate; keep a safe distance and position near an exit. Do not chase, touch or restrain an aggressive person. If you feel unsafe, step away to a safe location such as a vehicle, call 000 if there is any threat of harm, and notify management and the WHS Officer when safe.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control103\"></span> De-escalation briefed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control104\"></span> Disengagement route</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control105\"></span> Reporting pathway</label></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Psychosocial stress — isolation, workload, distressing events such as injured or dead wildlife</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Plan workloads realistically. Workers may raise fitness-for-duty concerns about themselves or a colleague with the Communication Officer, Project Manager or WHS Officer. A free, confidential Employee Assistance Program (1300 172 327) is available. Psychosocial support is provided after any distressing event.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control106\"></span> Workload reviewed</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control107\"></span> EAP briefed</label></td></tr>\n<tr><td colspan=\"3\" style=\"border:1px solid #cdd5db;background:#eef4ea;color:#2f7d3f;font-weight:700;padding:6px 10px\">Close-out</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;font-weight:600\">Personnel or equipment left on site; hazards left for others; incomplete records</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Headcount before leaving site. Retrieve or secure all equipment and traps; record device locations. Leave the site clean and gates as found. Complete the leaving-site check-in. Submit field forms, hazard reports and any incident reports through the digital WHS platform.</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;color:#5b6b76\"><label class=\"gswms__control-tick\"><span data-check=\"controls.control108\"></span> Headcount done</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control109\"></span> Equipment retrieved / recorded</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control110\"></span> Leaving-site check-in</label><label class=\"gswms__control-tick\"><span data-check=\"controls.control111\"></span> Forms submitted</label></td></tr>\n</tbody></table>\n<h2 style=\"break-before:page;font-size:16px;color:#fff;background:#2f7d3f;padding:9px 13px;margin:0\">High risk construction work — applicability and key controls</h2>\n<p style=\"font-size:10px;color:#5b6b76;margin:5px 0 8px\">All 19 high risk construction work categories under the WHS Regulation 2025 (NSW), the WHS Regulations 2011 (Cth) and the WHS Regulation 2011 (ACT). The Field Lead ticks every category that applies at the Daily Toolbox Talk. <strong>Where any category applies, the full task-specific SWMS must be reviewed, signed and followed in addition to this SWMS.</strong> The key controls below are a summary only and do not replace the full SWMS.</p>\n<table data-source-table=\"10\" style=\"width:100%;border-collapse:collapse;font-size:9.6px;margin:0 0 10px\">\n<thead><tr><th style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 8px;text-align:left;width:4%\">#</th><th style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 8px;text-align:left;width:24%\">High risk construction work category</th><th style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 8px;text-align:left;width:9%\">Applies</th><th style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 8px;text-align:left;width:10%\">EC SWMS</th><th style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 8px;text-align:left;width:53%\">Key controls (summary)</th></tr></thead>\n<tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">01</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Risk of a person falling more than two metres</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw01.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw01.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS01</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Survey from safe ground; keep a setback from edges, culverts, batters and banks; do not lean over or overreach; work in pairs; test edge stability; no climbing; fall-arrest only on a PC-verified anchorage with Working at Heights training.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">02</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work on a telecommunication tower</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw02.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw02.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken. Keep outside tower exclusion zones and fall-of-object zones; do not climb.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">03</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Demolition of a load-bearing or structurally significant element</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw03.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw03.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken. Keep outside demolition exclusion zones; survey only once the PC confirms the area is clear and safe.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">04</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work likely to involve disturbance of asbestos</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw04.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw04.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS04</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Observation only — never disturb, handle or remove ACM. Review the asbestos register; stay out of asbestos zones; no ground disturbance. If suspected asbestos is found: stop, do not disturb, isolate, report to the PC. Asbestos Awareness training (ACT).</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">05</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Temporary load-bearing support for structural alterations or repairs</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw05.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw05.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken. Do not enter or stand beneath propped or temporarily supported structures.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">06</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work in or near a confined space</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw06.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw06.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS06</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Treat culverts, drains, pits and voids as confined spaces until proven otherwise. No entry without a PC entry permit, atmospheric testing, a standby person, a non-entry rescue plan and RIIWHS202E. Inspect from the entrance with cameras where possible.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">07</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work in or near a shaft or trench deeper than 1.5 metres</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw07.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw07.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken. Never enter an excavation. Stay at least two metres from trench edges and spoil; fauna in trenches is rescued only from outside or by the PC once the trench is made safe.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">08</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work in or near a tunnel</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw08.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw08.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS08</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Go / no-go assessment before entry (air, structure, water, lighting, comms). Minimum two-person team with a communications officer outside; two light sources each; exit immediately if comms are lost or water rises.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">09</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Use of explosives</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw09.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw09.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken. Comply with all blast exclusion zones and clearance procedures; do not enter until the all-clear is given.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">10</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work on or near pressurised gas distribution mains or piping</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw10.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw10.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken. Review BYDA plans; no ground disturbance; do not drive star pickets near marked services. If you smell gas: withdraw upwind, no ignition sources, call 000 and the gas distributor.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">11</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work on or near chemical, fuel or refrigerant lines</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw11.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw11.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken. Keep clear; do not interfere with lines or valves; report leaks to the PC and withdraw.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">12</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work on or near energised electrical installations or services</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw12.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw12.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS12</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Observation only — never interfere with electrical assets. Keep Network Operator safe approach distances; never enter No-Go Zones; where voltage is unknown apply the greatest distance; keep equipment low; nothing stored or parked under lines. Treat unidentified services as live.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">13</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work in an area that may have a contaminated or flammable atmosphere</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw13.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw13.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS06 / SWMS08</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Atmospheric testing with a calibrated gas detector before and during entry; no ignition sources; exit on alarm or symptoms. Managed under the confined space and tunnel SWMS.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">14</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Tilt-up or precast concrete</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw14.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw14.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken. Stay outside crane and lift exclusion zones; never stand beneath a suspended load.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">15</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work on, in or adjacent to a road, railway, shipping lane or other traffic corridor</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw15.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw15.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS15</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Work only within an approved TMP / TGS set up by a qualified traffic control provider; never in a live lane; keep buffer distances; hi-vis worn; no traffic control by EC staff. Rail work: RIW / ARTC induction, approved possession and a Lookout Protection Officer.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">16</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work in an area with movement of powered mobile plant</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw16.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw16.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS16</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Never operate plant. Keep exclusion zones; never approach plant until the operator acknowledges you; never walk behind plant; use a spotter where required; plant stopped and isolated before fauna rescue.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">17</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work in areas with artificial extremes of temperature</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw17.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw17.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not normally applicable. Where cold rooms or heated plant spaces are encountered, do not enter without the site owner's procedure and a second person present.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">18</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Work in or near water or other liquid with a risk of drowning</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw18.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw18.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#eef4ea;font-weight:700;color:#2f7d3f\">SWMS18</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Survey from the bank where possible; buddy system with one person on land; no entry above waist depth or into fast, flooded or unknown water; PFD where required; throw rope (20 m) ready; reach or throw, do not go.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:700\">19</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;font-weight:600\">Diving work</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;white-space:nowrap\"><label class=\"gswms__control-tick\"><span data-risk=\"hrcw19.yes\"></span> Yes</label><label class=\"gswms__control-tick\"><span data-risk=\"hrcw19.no\"></span> No</label></td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top;background:#f4f7f2;font-weight:700;color:#82909b\">Not held</td><td style=\"border:1px solid #cdd5db;padding:7px 8px;vertical-align:top\">Not undertaken by Ecology Consulting.</td></tr>\n</tbody>\n</table>\n<div style=\"border:1px solid #d8c39e;background:#faf6ef;border-left:4px solid #b5854f;padding:8px 12px;font-size:9.8px;color:#5b4a2e;margin:0 0 14px\"><strong>Categories without an EC SWMS:</strong> Ecology Consulting does not undertake this work. If a survey requires work in or near any of these activities, <strong>stop, stay outside the exclusion zone and notify the Principal Contractor and the WHS Officer.</strong> Work does not proceed until the PC's controls are confirmed and, where EC staff will be exposed, a task-specific SWMS has been prepared and approved.</div>\n<table data-source-table=\"11\" style=\"width:100%;border-collapse:collapse;font-size:10px;margin:0 0 14px\">\n<thead><tr><th colspan=\"4\" style=\"border:1px solid #276834;background:#2f7d3f;color:#fff;padding:7px 9px;text-align:left\">Stop-work triggers — stop work immediately, move to a safe location, notify the Field Lead and Principal Contractor, and do not recommence until the risk is controlled and communicated</th></tr></thead><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;width:25%\">Emergency warning fire event, Catastrophic or Extreme fire danger</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;width:25%\">Lightning, storm or high wind</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;width:25%\">Flooding, rising water or unsafe crossings</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;width:25%\">Hazardous air quality or extreme heat</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;width:25%\">Missed or unacknowledged check-in</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;width:25%\">Loss of communication</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;width:25%\">Injury, illness or signs of heat stress</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;width:25%\">Threatening behaviour, or any situation where a worker feels unsafe</td></tr>\n</tbody></table>\n<h2 style=\"break-before:page;font-size:16px;color:#fff;background:#b5854f;padding:9px 13px;margin:0\">Emergency response</h2>\n<p style=\"font-size:10px;color:#5b6b76;margin:5px 0 10px\">Read with the site-specific Emergency Response Plan. The Field Lead is the Chief Warden. Any worker may activate the ERP.</p>\n<table data-source-table=\"12\" style=\"width:100%;border-collapse:collapse;font-size:10px;margin:0 0 12px\"><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:24%\">1 · Activate &amp; make safe</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Stop work and ensure the area is safe for responders. Do not move an injured person unless there is immediate danger. Where the area is unsafe — fire, flood, storm, aggressive person — move everyone to the Emergency Meeting Point or a vehicle before giving assistance. The Field Lead assesses the situation, initiates the response, directs evacuation to the Emergency Meeting Point, accounts for all personnel using the Daily Toolbox Talk sign-on sheet, and coordinates communication with the office.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">2 · Call for help</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Call 000 or 112, or activate the In Reach or PLB where there is no coverage. Provide GPS coordinates and the nearest cross roads, the nature of the emergency and safe access routes. Assign one person to guide responders in.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">3 · First aid</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">A trained first aider assesses the casualty, but only where it is safe to do so. Control bleeding, immobilise suspected fractures and monitor breathing. If unconscious but breathing, place in the recovery position; if not breathing, commence CPR. Record all treatment on the First Aid Treatment Log.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">4 · Post-incident</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">Report to the WHS Officer and complete an Incident Report Form within the required timeframe, submitted through the digital WHS platform. The WHS Officer updates the Incident Register and notifies the regulator of any notifiable incident. Attend debrief; review and update this SWMS and the ERP; restock emergency equipment used. Psychosocial support is provided where workers were exposed to distressing events.</td></tr>\n</tbody></table>\n<table data-source-table=\"13\" style=\"width:100%;border-collapse:collapse;font-size:10px;margin:0 0 14px\"><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;background:#eaf1f6;font-weight:700;width:26%\">Emergency services</td><td style=\"border:1px solid #cdd5db;padding:7px 9px\">000 or 112</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;background:#eaf1f6;font-weight:700;width:26%\">State Emergency Service (SES)</td><td style=\"border:1px solid #cdd5db;padding:7px 9px\">13 25 00</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;background:#eaf1f6;font-weight:700\">EC office / Check-in Officer</td><td style=\"border:1px solid #cdd5db;padding:7px 9px\">0472 569 988</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;background:#eaf1f6;font-weight:700\">Managing Director / WHS Officer</td><td style=\"border:1px solid #cdd5db;padding:7px 9px\">Tony Webster · 0448 439 334</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;background:#eaf1f6;font-weight:700\">Poisons Information Hotline</td><td style=\"border:1px solid #cdd5db;padding:7px 9px\">13 11 26</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;background:#eaf1f6;font-weight:700\">Wildlife rescue</td><td style=\"border:1px solid #cdd5db;padding:7px 9px\">1300 094 737</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:7px 9px;background:#eaf1f6;font-weight:700\">Employee Assistance Program</td><td style=\"border:1px solid #cdd5db;padding:7px 9px\">1300 172 327 — free and confidential</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;background:#eaf1f6;font-weight:700\">Nearest hospital &amp; muster point</td><td style=\"border:1px solid #cdd5db;padding:7px 9px\">Identified per site in the ERP; confirmed at the toolbox talk</td></tr>\n</tbody></table>\n<h3 style=\"font-size:14px;color:#fff;background:#2f7d3f;padding:8px 12px;margin:0\">Training &amp; competency requirements</h3>\n<table data-source-table=\"14\" style=\"width:100%;border-collapse:collapse;font-size:10px;margin:0 0 14px\"><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;width:26%\">Required for this activity</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">No additional task training beyond the baseline, except where a task-specific SWMS applies. Fauna Handling Training is required for anyone handling fauna. Snake Handling Training is required for anyone relocating snakes. Four-wheel-drive training is required for staff regularly driving unsealed or remote tracks. Bat handlers must hold current rabies (ABLV) vaccination.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Baseline — all field personnel</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">White Card (General Construction Induction); current driver's licence of appropriate class; CPR certification (annual renewal); Provide First Aid (HLTAID011), and Remote First Aid (HLTAID013) for remote or isolated work; General Fauna Handling Training.</td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:6px 9px;background:#f4f7f2;font-weight:700;\">Verification</td><td style=\"border:1px solid #cdd5db;padding:7px 9px;vertical-align:top;\">All training must be current, recorded and verifiable prior to mobilisation. Records are maintained by the Administration Officer and retained for a minimum of five years, with expiry notifications issued in advance; workers are not mobilised with expired mandatory training. Competency is verified annually and observed on site by Principal or Senior Ecologists, Project Managers and the WHS Officer. Subcontractor training evidence is collected and retained for audit.</td></tr>\n</tbody></table>\n<h2 style=\"break-before:page;font-size:16px;color:#fff;background:#2f7d3f;padding:9px 13px;margin:0\">Daily SWMS acknowledgement &amp; sign-on register</h2>\n<p style=\"font-size:10px;color:#5b6b76;margin:5px 0 10px\">All personnel must read, understand and sign this SWMS before commencing work, confirming they are fit for duty, competent and able to perform assigned tasks safely. Completed with the Daily Toolbox Talk and submitted through the digital WHS platform.</p>\n<table data-source-table=\"15\" style=\"width:100%;border-collapse:collapse;font-size:10px;margin:0 0 14px\">\n<thead><tr>\n<th style=\"border:1px solid #2f7fb5;background:#3f93cf;color:#fff;padding:7px 9px;text-align:left;width:6%\">#</th>\n<th style=\"border:1px solid #2f7fb5;background:#3f93cf;color:#fff;padding:7px 9px;text-align:left;width:30%\">Name</th>\n<th style=\"border:1px solid #2f7fb5;background:#3f93cf;color:#fff;padding:7px 9px;text-align:left;width:22%\">Role</th>\n<th style=\"border:1px solid #2f7fb5;background:#3f93cf;color:#fff;padding:7px 9px;text-align:left;width:24%\">Signature</th>\n<th style=\"border:1px solid #2f7fb5;background:#3f93cf;color:#fff;padding:7px 9px;text-align:left;width:18%\">Date</th>\n</tr></thead><tbody>\n<tr><td style=\"border:1px solid #cdd5db;padding:12px 9px\">1</td><td data-blank-field=\"team.0.name\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.0.name\"></span></td><td data-blank-field=\"team.0.role\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.0.role\"></span></td><td data-blank-field=\"team.0.signature\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.0.signature\"></span></td><td data-blank-field=\"team.0.date\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.0.date\"></span></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:12px 9px\">2</td><td data-blank-field=\"team.1.name\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.1.name\"></span></td><td data-blank-field=\"team.1.role\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.1.role\"></span></td><td data-blank-field=\"team.1.signature\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.1.signature\"></span></td><td data-blank-field=\"team.1.date\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.1.date\"></span></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:12px 9px\">3</td><td data-blank-field=\"team.2.name\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.2.name\"></span></td><td data-blank-field=\"team.2.role\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.2.role\"></span></td><td data-blank-field=\"team.2.signature\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.2.signature\"></span></td><td data-blank-field=\"team.2.date\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.2.date\"></span></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:12px 9px\">4</td><td data-blank-field=\"team.3.name\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.3.name\"></span></td><td data-blank-field=\"team.3.role\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.3.role\"></span></td><td data-blank-field=\"team.3.signature\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.3.signature\"></span></td><td data-blank-field=\"team.3.date\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.3.date\"></span></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:12px 9px\">5</td><td data-blank-field=\"team.4.name\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.4.name\"></span></td><td data-blank-field=\"team.4.role\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.4.role\"></span></td><td data-blank-field=\"team.4.signature\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.4.signature\"></span></td><td data-blank-field=\"team.4.date\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.4.date\"></span></td></tr>\n<tr><td style=\"border:1px solid #cdd5db;padding:12px 9px\">6</td><td data-blank-field=\"team.5.name\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.5.name\"></span></td><td data-blank-field=\"team.5.role\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.5.role\"></span></td><td data-blank-field=\"team.5.signature\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.5.signature\"></span></td><td data-blank-field=\"team.5.date\" style=\"border:1px solid #cdd5db;padding:12px 9px\"><span data-field=\"team.5.date\"></span></td></tr>\n</tbody></table>\n<p style=\"font-size:8.5px;color:#82909b;margin:0\">© Ecology Consulting Pty Ltd 2026 · Reviewed and approved by the WHS Officer. Review annually or following any incident, near miss, audit finding or change to legislation, work practice or site conditions.</p>\n</article>";
